        let mut guard = lock.lock().unwrap();
        guard.flag = true;
        cvar.notify_one();
        // lock released when guard drops
    });

    waiter.join().unwrap();
    notifier.join().unwrap();

    let (lock, _) = &*shared;
    let guard = lock.lock().unwrap();
