    // Wake all waiters.
    {
        let (lock, cvar) = &*pair;
        let mut guard = lock.lock().unwrap();
        guard.1 = true;
        cvar.notify_all();
    }

    for h in handles {
        h.join().unwrap();
    }

    let (lock, _) = &*pair;
    let guard = lock.lock().unwrap();
    let remaining = 2 - guard.0;
    println!("DONE waiters={}", remaining);
}

