                let mut count = m.lock().unwrap();
                *count += 1;
                c.notify_all();
            }
            // Wait on shared condvar while holding own lock.
            while !*guard {
                guard = condvar.wait(guard).unwrap();
            }
        }));
    }

    // Notifier
    {
