        let lock1 = Arc::clone(&lock1);
        let lock2 = Arc::clone(&lock2);
        let announced = Arc::clone(&announced);
        handles.push(thread::spawn(move || {
            // Wait until both waiters have announced.
            {
                let (m, c) = &*announced;
