        p2.acquire();
        lb.acquire();
        // Critical section: hold both locks.
        // ... work ...
        lb.release();
        la.release();
        let (m, cv) = &*da;
        let mut d = m.lock().unwrap();
        *d = true;
        cv.notify_one();
    });

    // Worker 2: takes lock_b first, then waits for worker1's signal, then lock_a.
    let (la, lb, p1, p2, db) = (
        lock_a.clone(),
        lock_b.clone(),
        permit1.clone(),
        permit2.clone(),
        done_b.clone(),
