        let _g_a = a_lock_a.lock().unwrap();

        // Signal that we have taken our first lock.
        a_permit1.release();

        // Wait until the other worker has taken its first lock.
        a_permit2.acquire();

        // Now take the second lock.
        let _g_b = a_lock_b.lock().unwrap();

