        let l1 = Arc::clone(&lock1);
        let l3 = Arc::clone(&lock3);
        handles.push(thread::spawn(move || {
            let _g1 = l1.lock().unwrap();
            let _g3 = l3.lock().unwrap();
            // critical work with both locks held
        }));
    }

    for h in handles {
        h.join().unwrap();
    }

    println!("DONE done=1");
}
